function findDuplicates(array) {
  const dups = new Set();
  const sortedArray = array.sort((a, b) => a - b);

  for (let index = 1; index < sortedArray.length; index++) {
    const element = sortedArray[index];
    const previous = sortedArray[index - 1];
    if (element === previous) {
      dups.add(element);
    }
  }
  return [...dups];
}
