 * @returns {number} - The length of the longest unique substring.
 */
function lenLongestSubstring(s) {
  // write your code here...
  let max = 0;
  const set = new Set();

  for (let i = 0, j = 0; j < s.length; j++) {
    while (set.has(s[j])) set.delete(s[i++]);
