function isOneEditAway(str1, str2) {
  let edit = 0;
  let i1, i2;

  if(Math.abs(str1.length - str2.length) > 1) {
    return false;
  }

  for(i1 = 0, i2 = 0; i1 < str1.length && i2 < str2.length; i1++, i2++) {
