// Strings are inmutable. You cannot do: s='abc'; s[1]='d';
function urlify(str, length) {
  let string = str.split('');

  for(let k = string.length-1, i=length-1; i >= 0; i--, k--) {
    const char = string[i];
    if(char === ' ') {
      string[k] = '0';
      string[--k] = '2';
      string[--k] = '%';
    } else {
      string[k] = char;
    }
  }

  return string.join('');
