console.log('Flat with depth 2:', flattenSimple(nestedArray, 2));
// Output: [1, 2, 3, 4, 5, 6, [7], 8]

console.log('Deep flatten (Infinity):', flattenDeep(nestedArray));
// Output: [1, 2, 3, 4, 5, 6, 7, 8]

console.log('Recursive flatten:', flattenRecursive(nestedArray));
