class List {
  constructor(dataStore = [], listSize = 0, pos = 0) {
    this.dataStore = dataStore;
    this.listSize  = listSize;
    this.pos       = pos;
  }

  clear() {
    this.dataStore = [];
    this.pos       = 0;
    this.listSize  = 0;
  }

  find(element) {
    return this.dataStore.findIndex(e => e === element);
  }

  insert(element, after) {
    const insertPos = this.find(after);
    if (insertPos != -1 ) {
      this.dataStore.splice(insertPos+1, 0, element);
      this.listSize++;
      return true;
    }
    return false;
  }

  append(element) {
    this.dataStore = [...this.dataStore, element];
    this.listSize++;
  }

  remove(element) {
    const removePos = this.find(element);
    if(removePos != -1) {
      this.dataStore.splice(removePos, 1);
      this.listSize--;
      return true;
    }
    return false;
  }

  front() {
    this.pos = 0;
  }

  end() {
    this.pos = this.listSize - 1;
  }

  prev() {
    if (this.pos > 0) {
      --this.pos;
    }
  }

  next() {
    if (this.pos < this.listSize - 1) {
      ++this.pos;
    }
  }

  length() {
    return this.listSize;
  }

  currPos() {
    return this.pos;
  }

  moveTo(position) {
    this.pos = position
  }

  getElement() {
    return this.dataStore[this.pos];
  }

  contains(element) {
    return (this.dataStore.find(value => value === element) != undefined ) ? true : false;
  }

  displayList() {
    this.dataStore.forEach((item, counter) => {
      console.log(`${counter + 1}.- ${item}`);
    })
  }

  toString() {
    return JSON.stringify(this.dataStore);
  }
}
