    let upperBound = dataStore.length - 1
    let lowerBound = 0
    while (lowerBound <= upperBound) {
      let mid = Math.floor((lowerBound + upperBound) / 2)
      if (dataStore[mid] < data) {
        lowerBound = mid + 1
      } else if (dataStore[mid] > data) {
        upperBound = mid - 1
      } else {
        return mid
      }
