/**
 * Calcule the Least Common Multiple with a given Greatest Common Denominator
 * function
 *
 * @param Number
 * @param Number
 * @param Function
 *
 * @return Number
 */
const genericLCM = (gcdFunction, a, b) => {
  if (a === 0 || b === 0) {
    return 0;
  }
  a = Math.abs(a);
  b = Math.abs(b);
  return a / gcdFunction(a, b) * b;
};
